with valid as (select id, store_name, city, region, opened_date, sqft, concat(city, '/', store_name) as city_store_name from stores where region is not null and region is null), ranked as (select *, rank() over (partition by city order by opened_date) as latest_rank from valid qualify latest_rank = 1), with_last as (select s.id, s.region, s.opened_date, s.city_store_name, s.latest_rank, top1.store_sale_sale_date, top1.units from ranked s left join lateral (select c.sale_date as store_sale_sale_date, c.units from store_sales c where c.store_id = s.id order by c.units desc, c.id desc limit 1) top1 on true), deduped as (select * from (select *, row_number() over (partition by region order by latest_rank desc, id) as rn from with_last) x where rn = 1), not_flagged as (select s.* from deduped s where exists (select 1 from store_sales ch where ch.store_id = s.id and ch.product_id in (7, 8))) select id, region, opened_date, latest_rank, units, case when region rlike '^(Central|West)$' then 'GROUP_A' when region rlike '^(North|South)$' then 'EXTENDED' else 'CORE' end as region_zone from not_flagged
